export const SHELL_CACHE='spotlight-shell-v3';
export const AUDIO_CACHE='spotlight-audio-v1';
export const SHELL=['./','./index.html','./styles.css','./mobile.css','./app.js','./core.mjs','./offline.js','./data.json','./audio-manifest.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
let stop=false;
export function cancelDownload(){stop=true;}
export async function offlineStatus(manifest){if(!('caches' in globalThis))return {supported:false,count:0,total:manifest.length,shell:false};const cache=await caches.open(AUDIO_CACHE);const keys=new Map((await cache.keys()).map(r=>[r.url,r]));let count=0;for(const item of manifest){const key=keys.get(new URL(item.url,location.href).href);if(!key)continue;const response=await cache.match(key);if(response&&Number(response.headers.get('x-audio-bytes'))===item.bytes)count++;}const shell=await caches.open(SHELL_CACHE);const ready=(await Promise.all(SHELL.map(url=>shell.match(new URL(url,location.href).href)))).every(Boolean);return {supported:true,count,total:manifest.length,shell:ready};}
export async function downloadAll(manifest,onProgress){stop=false;await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Offline setup timed out')),15000))]);await navigator.storage?.persist?.().catch(()=>false);const cache=await caches.open(AUDIO_CACHE);let count=0;let next=0;let failure=null;async function worker(){while(next<manifest.length&&!stop&&!failure){const item=manifest[next++];try{const old=await cache.match(item.url);if(!old||Number(old.headers.get('x-audio-bytes'))!==item.bytes){const response=await fetch(item.url,{cache:'no-store'});if(!response.ok||response.status!==200)throw Error('Audio download failed: '+response.status);const bytes=await response.arrayBuffer();if(bytes.byteLength!==item.bytes||new DataView(bytes).getUint32(0)!==0x52494646)throw Error('Audio verification failed');await cache.put(item.url,new Response(bytes,{headers:{'content-type':'audio/wav','content-length':String(bytes.byteLength),'x-audio-bytes':String(bytes.byteLength)}}));}count++;onProgress(count,manifest.length);}catch(error){failure=error;}}}await Promise.all(Array.from({length:3},worker));if(failure)throw failure;return offlineStatus(manifest);}
